// Independent invariant checker: canonicalize, restrict guarded domains, pull back XOR, then exact inclusion.
#include <bits/stdc++.h>
using namespace std;struct Node{int v,l,h;};struct Key{int v,l,h;bool operator==(const Key&o)const{return v==o.v&&l==o.l&&h==o.h;}};struct Hash{size_t operator()(const Key&k)const{return ((uint64_t)k.l*1000000007ULL)^((uint64_t)k.h*1000033ULL)^k.v;}};
struct Manager{int n;vector<Node>a;unordered_map<Key,int,Hash>intern;unordered_map<uint64_t,bool>submemo;Manager(int n):n(n),a{{n,0,0},{n,1,1}}{}
 int make(int v,int l,int h){if(l==h)return l;Key k{v,l,h};auto it=intern.find(k);if(it!=intern.end())return it->second;int id=a.size();a.push_back({v,l,h});intern[k]=id;return id;}
 int pull(int root,uint64_t mask,uint64_t val,uint64_t flip,uint64_t clear=0){unordered_map<int,int>memo;function<int(int)>go=[&](int u){if(u<2)return u;auto it=memo.find(u);if(it!=memo.end())return it->second;Node z=a[u];int ans;if((clear>>z.v)&1)ans=go(z.l);else if((mask>>z.v)&1)ans=go(((val^flip)>>z.v)&1?z.h:z.l);else{int l=go(z.l),h=go(z.h);if((flip>>z.v)&1)swap(l,h);ans=make(z.v,l,h);}memo[u]=ans;return ans;};return go(root);}
 bool subset(int f,int g){if(f==0||g==1||f==g)return true;if(f==1&&g==0)return false;uint64_t key=((uint64_t)f<<32)|(uint64_t)g;auto it=submemo.find(key);if(it!=submemo.end())return it->second;Node x=a[f],y=a[g];int v=min(x.v,y.v);assert(v<n);bool ans=subset(x.v==v?x.l:f,y.v==v?y.l:g)&&subset(x.v==v?x.h:f,y.v==v?y.h:g);submemo[key]=ans;return ans;}
 uint64_t count(int root){unordered_map<int,uint64_t>memo;function<uint64_t(int)>go=[&](int u)->uint64_t{if(u<2)return u;auto it=memo.find(u);if(it!=memo.end())return it->second;Node z=a[u];return memo[u]=(go(z.l)<<(a[z.l].v-z.v-1))+(go(z.h)<<(a[z.h].v-z.v-1));};return go(root)<<a[root].v;}
};
int main(int argc,char**argv){try{if(argc!=4)throw runtime_error("graph invariant output");ifstream f(argv[1]);int n,np,nt,nr,sp;uint64_t sk,sv;f>>n>>np>>nt>>nr>>sp>>sk>>sv;assert(n>=0&&n<63&&sp>=0&&sp<np&&(sv&~sk)==0);vector<array<long long,8>>t(nt);for(auto&r:t)for(long long&x:r)f>>x;vector<int>re(nr);for(int&x:re)f>>x;string extra;if(!f||(f>>extra))throw runtime_error("graph format");
 ifstream b(argv[2]);int nn,bn,bp;b>>bn>>bp>>nn;assert(bn==n&&bp==np&&nn>=2);Manager m(n);vector<Node>orig(nn);vector<int>ids(nn);for(int i=0;i<nn;i++){auto&z=orig[i];b>>z.v>>z.l>>z.h;if(i<2){assert(z.v==n&&z.l==i&&z.h==i);ids[i]=i;}else{assert(z.v>=0&&z.v<n&&z.l>=0&&z.l<i&&z.h>=0&&z.h<i&&z.l!=z.h&&orig[z.l].v>z.v&&orig[z.h].v>z.v);ids[i]=m.make(z.v,ids[z.l],ids[z.h]);}}
 vector<int>roots(np);for(int&r:roots){int x;b>>x;assert(x>=0&&x<nn);r=ids[x];}if(!b||(b>>extra))throw runtime_error("bdd format");uint64_t states=0;for(int r:roots)states+=m.count(r);
 if(m.pull(roots[sp],sk,sv,0)!=1)throw runtime_error("initial cube missing");int checks=1;for(auto r:t){auto[src,dst,k,v,flip,clear,goal,packet]=r;assert(src>=0&&src<np&&dst>=0&&dst<np&&k>=0&&v>=0&&flip>=0&&(v&~k)==0);int allowed=m.pull(roots[src],k,v,0);if(goal){if(allowed)throw runtime_error("goal intersects invariant");}else{int dest=m.pull(roots[dst],k,v,flip,clear);if(!m.subset(allowed,dest))throw runtime_error("guarded XOR/clear escapes invariant");}checks++;}for(int dst:re){assert(dst>=0&&dst<np);if(!m.subset(roots.back(),roots[dst]))throw runtime_error("OUT escapes");checks++;}
 ofstream out(argv[3]);out<<"{\"status\":\"PASS independent canonical restriction/XOR/clear invariant check\",\"variables\":"<<n<<",\"positions\":"<<np<<",\"certificate_nodes\":"<<nn<<",\"invariant_states\":"<<states<<",\"checks\":"<<checks<<",\"canonical_nodes\":"<<m.a.size()<<"}\n";cout<<"PASS "<<states<<" states; "<<checks<<" checks\n";
 }catch(exception&e){cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
